function clone(value) { return JSON.parse(JSON.stringify(value)); }
function uid(prefix) { return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`; }
function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) || "null");
    if (saved && Array.isArray(saved.properties) && Array.isArray(saved.leads)) {
      const shouldSeed = saved.demoSeedVersion !== 4;
      const propertyIds = new Set(saved.properties.map((item) => item.id));
      const leadIds = new Set(saved.leads.map((item) => item.id));
      const migrated = { ...saved, demoSeedVersion: 4, properties: shouldSeed ? [...saved.properties, ...demoProperties.filter((item) => !propertyIds.has(item.id))] : saved.properties, leads: shouldSeed ? [...saved.leads, ...demoLeads.filter((item) => !leadIds.has(item.id))] : saved.leads, favorites: Array.isArray(saved.favorites) ? saved.favorites : [] };
      if (shouldSeed) localStorage.setItem(KEY, JSON.stringify(migrated));
      return migrated;
    }
  } catch {}
  return { demoSeedVersion: 4, properties: clone(demoProperties), leads: clone(demoLeads), favorites: [] };
}
function save() { localStorage.setItem(KEY, JSON.stringify(state)); updateNavCount(); }
function esc(value = "") { return String(value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char])); }
function money(property) { return new Intl.NumberFormat("es-MX", { style: "currency", currency: property.currency || "MXN", maximumFractionDigits: 0 }).format(Number(property.price || 0)); }
function toast(message) { const node = document.getElementById("toast"); node.textContent = message; node.classList.add("show"); clearTimeout(toastTimer); toastTimer = setTimeout(() => node.classList.remove("show"), 2600); }
function updateNavCount() { const count = document.getElementById("nav-leads"); if (count) count.textContent = String(state.leads.filter((lead) => !["Ganado", "Perdido"].includes(lead.stage)).length); }
function go(next) { view = next; document.querySelectorAll(".nav-link").forEach((button) => button.classList.toggle("active", button.dataset.view === next)); document.querySelector(".main-nav")?.classList.remove("open"); render(); app.focus({ preventScroll: true }); window.scrollTo({ top: 0, behavior: "smooth" }); }
function statusClass(status) { return status === "Reservada" ? "reservada" : status === "Vendida" ? "vendida" : status === "Borrador" ? "borrador" : ""; }
function propertyById(id) { return state.properties.find((item) => item.id === id); }
function imageTag(src, alt, className = "") { return src ? `<img class="${className}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="photo-placeholder" hidden>N</div>` : `<div class="photo-placeholder">N</div>`; }
function render() { if (view === "public") renderPublic(); else if (view === "admin") renderAdmin(); else renderCrm(); }

