  const filtered = all.filter((item) => `${item.title} ${item.zone} ${item.type}`.toLowerCase().includes(adminFilter.search.toLowerCase()) && (adminFilter.status === "Todos" || item.status === adminFilter.status));
  app.innerHTML = `<div class="page-shell"><div class="page-heading"><div><span class="section-label">PANEL DE ADMINISTRACIÓN</span><h1>Inventario de propiedades</h1><p>Administra las fichas y decide qué aparece en el sitio público.</p></div><div class="page-actions"><button class="button button-light" data-action="export">Exportar demo ↓</button><button class="button button-green" data-action="new-property">＋ Nueva propiedad</button></div></div><div class="demo-note"><span>ⓘ</span><span><b>Entorno de demostración.</b> Las fichas y solicitudes de ejemplo son ficticias. Todo lo que agregues aquí se refleja en el sitio público y en el CRM de este navegador.</span></div><div class="admin-layout"><aside class="admin-sidebar"><div class="admin-account"><span class="avatar">N</span><span><b>Norte Inmobiliaria</b><small>Espacio de demostración</small></span></div><span class="mobile-admin-nav">Administración</span><nav class="side-nav"><button class="active" data-action="admin-inventory">▦ Inventario <span class="side-count">${all.length}</span></button><button data-view="crm">♧ Solicitudes y CRM <span class="side-count">${pending}</span></button><button data-view="public">↗ Ver sitio público</button></nav><div class="side-note">La publicación es inmediata en esta demo. En un producto real se pueden agregar perfiles, permisos y aprobación editorial.</div></aside><section class="admin-main"><div class="stats-grid"><article class="stat-card"><span>Propiedades totales</span><strong>${all.length}</strong><small>Registros en inventario</small></article><article class="stat-card"><span>Visibles en el sitio</span><strong>${active}</strong><small>Publicadas y no vendidas</small></article><article class="stat-card"><span>Disponibles</span><strong>${available}</strong><small>Listas para consulta</small></article><article class="stat-card"><span>Contactos abiertos</span><strong>${pending}</strong><small>Por atender en el CRM</small></article></div><section class="admin-panel"><div class="panel-head"><div><h2>Inventario</h2><p>Actualiza el estado, edita la ficha o publícala en el sitio.</p></div><span class="property-counter">${filtered.length} registros</span></div><div class="inventory-toolbar"><input class="input-search" id="inventory-search" placeholder="Buscar propiedad o zona…" value="${esc(adminFilter.search)}"><select class="filter-select" id="inventory-status"><option>Todos</option>${["Disponible", "Reservada", "Vendida", "Borrador"].map((status) => `<option ${adminFilter.status === status ? "selected" : ""}>${status}</option>`).join("")}</select><button class="button button-light button-small" data-action="new-property">＋ Agregar inmueble</button></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Propiedad</th><th>Precio</th><th>Estado</th><th>Sitio público</th><th>Actualizada</th><th>Acciones</th></tr></thead><tbody>${filtered.length ? filtered.map(inventoryRow).join("") : `<tr><td colspan="6" class="table-empty">No hay propiedades con esos filtros.</td></tr>`}</tbody></table></div></section><section class="admin-panel"><div class="panel-head"><div><h2>Herramientas del demo</h2><p>Guarda una copia o recupera la información inicial de ejemplo.</p></div></div><div class="data-tools"><button class="button button-light button-small" data-action="export">Descargar copia JSON ↓</button><label class="button button-light button-small" for="import-file">Importar copia ↑</label><input id="import-file" type="file" accept="application/json" hidden><button class="button button-danger button-small" data-action="reset-demo">Restablecer datos de muestra</button></div></section></section></div></div>`;
  document.getElementById("inventory-search").addEventListener("input", (event) => { adminFilter.search = event.target.value; const start = event.target.selectionStart; const end = event.target.selectionEnd; renderAdmin(); const input = document.getElementById("inventory-search"); input.focus(); input.setSelectionRange(start, end); });
  document.getElementById("inventory-status").addEventListener("change", (event) => { adminFilter.status = event.target.value; renderAdmin(); });
